/* Audio feature extraction runs outside the UI thread. No upload or remote model. */
'use strict';
importScripts('timing.js?v=4.0.2');
let paused=false,cancelled=false;
onmessage=e=>{if(e.data.type==='pause')paused=e.data.value;if(e.data.type==='cancel')cancelled=true;if(e.data.type==='timing'){cancelled=false;paused=false;DCTiming.detect(new Float32Array(e.data.samples),e.data.sampleRate,e.data.options,checkpoint,(value,detail)=>postMessage({type:'progress',value,detail})).then(timing=>postMessage({type:'timingDone',timing})).catch(err=>postMessage({type:'error',message:err.message}));}if(e.data.type==='analyze')analyze(e.data).catch(err=>postMessage({type:'error',message:err.message}));};
async function checkpoint(){await new Promise(r=>setTimeout(r,0));while(paused&&!cancelled)await new Promise(r=>setTimeout(r,45));if(cancelled)throw Error('已取消');}
function fft(re,im){const n=re.length;for(let i=1,j=0;i<n;i++){let bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j){[re[i],re[j]]=[re[j],re[i]];[im[i],im[j]]=[im[j],im[i]];}}
 for(let len=2;len<=n;len<<=1){const a=-2*Math.PI/len,wr0=Math.cos(a),wi0=Math.sin(a);for(let i=0;i<n;i+=len){let wr=1,wi=0;for(let j=0;j<len/2;j++){const p=i+j,q=p+len/2,tr=re[q]*wr-im[q]*wi,ti=re[q]*wi+im[q]*wr;re[q]=re[p]-tr;im[q]=im[p]-ti;re[p]+=tr;im[p]+=ti;const v=wr*wr0-wi*wi0;wi=wr*wi0+wi*wr0;wr=v;}}}}
const percentile=(a,p)=>{const b=a.slice().sort((x,y)=>x-y);return b[Math.min(b.length-1,Math.floor(b.length*p))]||1e-8;};
async function analyze({samples,sampleRate,bpm}){cancelled=false;paused=false;const audio=new Float32Array(samples),n=2048,hop=Math.max(256,2**Math.round(Math.log2(sampleRate/43))),dt=hop/sampleRate,count=Math.ceil(audio.length/hop),frames=[],prev=new Float64Array(n/2),hann=Float64Array.from({length:n},(_,i)=>.5-.5*Math.cos(2*Math.PI*i/(n-1))),bandCenters=Array.from({length:24},(_,i)=>20*Math.pow(sampleRate/2/20,(i+.5)/24));
 const binBand=Array.from({length:n/2},(_,k)=>Math.max(0,Math.min(23,Math.floor(Math.log(Math.max(20,k*sampleRate/n)/20)/Math.log(sampleRate/2/20)*24))));let rmsTotal=0;const spectralTotals=new Float64Array(n/2);
 for(let f=0;f<count;f++){const re=new Float64Array(n),im=new Float64Array(n),start=f*hop;let sum=0,peak=0;for(let i=0;i<n;i++){const v=audio[start+i]||0;sum+=v*v;peak=Math.max(peak,Math.abs(v));re[i]=v*hann[i];}fft(re,im);let flux=0,fluxDen=0;const bands=Array(24).fill(0),bandFlux=Array(24).fill(0);
  for(let k=1;k<n/2;k++){const mag=Math.hypot(re[k],im[k])/n;spectralTotals[k]+=mag*mag;bands[binBand[k]]+=mag*mag;const log=Math.log1p(mag*1000);flux+=Math.max(0,log-prev[k]);bandFlux[binBand[k]]+=Math.max(0,log-prev[k]);fluxDen+=log;prev[k]=log;}
  const rms=Math.sqrt(sum/n);rmsTotal+=rms;frames.push({bandFlux,rms,peak,db:Math.max(-96,20*Math.log10(rms+1e-9)),bands:bands.map(v=>Math.sqrt(v)*2),flux:flux/Math.max(1,fluxDen),onset:0});
  if(f%96===0){postMessage({type:'progress',value:Math.round(f/count*85),detail:`频谱与鼓点 · ${Math.round(start/sampleRate)} / ${Math.round(audio.length/sampleRate)} 秒`});await checkpoint();}}
 const fluxScale=percentile(frames.map(f=>f.flux),.94),onsetTimes=[];
 for(let i=0;i<frames.length;i++){let avg=0,num=0;for(let j=Math.max(0,i-14);j<=Math.min(frames.length-1,i+14);j++){avg+=frames[j].flux;num++;}frames[i].onset=Math.max(0,Math.min(1,(frames[i].flux-avg/num*.75)/(fluxScale*.9||1)));if(i>0&&i<frames.length-1&&frames[i].flux>=frames[i-1].flux&&frames[i].flux>frames[i+1].flux&&frames[i].onset>.26&&frames[i].db>-55){const t=i*dt;if(!onsetTimes.length||t-onsetTimes.at(-1).time>.08)onsetTimes.push({time:t,strength:frames[i].onset});}}
 postMessage({type:'progress',value:88,detail:'比较能量、频谱与重复段落…'});await checkpoint();
 const duration=audio.length/sampleRate,segDur=Math.max(4,32*60/(bpm||120)),sections=[];
 for(let t=0;t<duration;t+=segDur){const first=Math.floor(t/dt),last=Math.min(frames.length,Math.floor((t+segDur)/dt)),fs=frames.slice(first,last);if(!fs.length)continue;const energy=fs.reduce((s,f)=>s+f.rms,0)/fs.length,vec=Array(24).fill(0);for(const f of fs)for(let k=0;k<24;k++)vec[k]+=f.bands[k];const norm=Math.hypot(...vec)||1;for(let k=0;k<24;k++)vec[k]/=norm;const onset=onsetTimes.filter(o=>o.time>=t&&o.time<t+segDur),gaps=onset.slice(1).map((o,i)=>o.time-onset[i].time),avg=gaps.reduce((a,b)=>a+b,0)/(gaps.length||1),variance=gaps.reduce((s,g)=>s+(g-avg)**2,0)/(gaps.length||1);const regularity=avg?Math.max(0,1-Math.sqrt(variance)/avg):0;
  sections.push({start:t,end:Math.min(duration,t+segDur),energy,vec,regularity,onsetRate:onset.length/segDur,kind:'verse',repeat:'',color:'#77b7d9',manual:false});}
 let labels=0;for(let i=0;i<sections.length;i++){const s=sections[i];let match=-1,best=0;for(let j=0;j<i-1;j++){const p=sections[j],cos=s.vec.reduce((v,x,k)=>v+x*p.vec[k],0),energyRatio=Math.min(s.energy,p.energy)/Math.max(s.energy,p.energy,1e-7),rhythm=1-Math.min(1,Math.abs(s.onsetRate-p.onsetRate)/Math.max(1,s.onsetRate,p.onsetRate));const sim=cos*.65+energyRatio*.2+rhythm*.15;if(sim>best){best=sim;match=j;}}s.similarity=best;if(best>.94&&match>=0){if(!sections[match].repeat)sections[match].repeat=String.fromCharCode(65+labels++%26);s.repeat=sections[match].repeat;s.repeatOf=match;}}
 const median=percentile(sections.map(s=>s.energy),.52);for(const s of sections){s.kind=s.energy>=median*1.04||s.repeat&&s.energy>=median?'chorus':'verse';s.color=s.kind==='chorus'?'#c48bdf':'#77b7d9';s.confidence=Math.min(.88,.45+Math.abs(s.energy-median)/(median||1)*.45);delete s.vec;}
 const totalEnergy=spectralTotals.reduce((sum,v)=>sum+v,0);let cumulative=0,lowBin=1,highBin=n/2-1;for(let k=1;k<spectralTotals.length;k++){cumulative+=spectralTotals[k];if(cumulative<totalEnergy*.0005)lowBin=k;if(cumulative<totalEnergy*.9995)highBin=k;}const frequencyBounds=totalEnergy>1e-12?{min:Math.max(20,lowBin*sampleRate/n),max:Math.min(sampleRate/2,(highBin+1)*sampleRate/n)}:{min:20,max:sampleRate/2};
 postMessage({type:'progress',value:99,detail:'整理波形与段落标记…'});await checkpoint();postMessage({type:'done',analysis:{version:3,windowSize:n,frequencyBounds,duration,hop:dt,sampleRate,bandCenters,frames,onsetTimes,sections,rmsMean:rmsTotal/frames.length}});
}
